/**
 * Add direct submenu entry for the document/environment tab.
 *
 * The Codestar settings page renders this section as an internal tab by default;
 * this submenu only provides a left-admin shortcut to the same tab and does not
 * add any update/license/remote action.
 */
function zib_add_document_environment_submenu()
{
    add_submenu_page(
        'zibll_options',
        '文档&环境',
        '文档&环境',
        'manage_options',
        'zibll_options#tab=' . sanitize_title('文档环境'),
        '__return_null'
    );
}
add_action('admin_menu', 'zib_add_document_environment_submenu', 99);

//后台主题设置
function zib_csf_admin_options()
{
    //只有后台才执行此代码
    if (!is_admin()) {
        return;
    }

    $prefix    = 'zibll_options';
    $no_create = ((wp_doing_ajax() && (empty($_POST['action']) || !strstr($_POST['action'], 'csf_' . $prefix))) || (!wp_doing_ajax() && (empty($_GET['page']) || $_GET['page'] !== $prefix)));

    //开始构建
    CSF::createOptions($prefix, array(
        'menu_title'         => 'zibll主题设置',
        'menu_slug'          => 'zibll_options',
        'framework_title'    => '子比主题',
        'show_in_customizer' => false, //在wp-customize中也显示相同的选项
        'save_defaults'      => !$no_create, //首次安装自动保存默认设置：全部加载时，再自动保存，避免保存的设置丢失
        'footer_text'        => '更优雅的wordpress主题-Zibll主题 V' . wp_get_theme()['Version'],
        'footer_credit'      => '<i class="fa fa-fw fa-heart-o" aria-hidden="true"></i> ',
        'theme'              => 'light',
    ));

    $imagepath = get_template_directory_uri() . '/img/';
    $f_imgpath = get_template_directory_uri() . '/inc/csf-framework/assets/images/';
    $new_badge = zib_get_csf_option_new_badge();

    //必须先添加一个，不然后台不显示菜单
    CSF::createSection($prefix, array(
        'id'    => 'basic',
        'title' => '全局&功能',
        'icon'  => 'fa fa-fw fa-bullseye',
    ));

    CSF::createSection($prefix, array(
        'id'    => 'page',
        'title' => '页面&显示',
        'icon'  => 'fa fa-fw fa-calendar-check-o',
    ));
    CSF::createSection($prefix, array(
        'id'    => 'post',
        'title' => '文章&列表',
        'icon'  => 'fa fa-fw fa-map-o',
    ));
    CSF::createSection($prefix, array(
        'id'    => 'cap',
        'title' => '功能&权限',
        'icon'  => 'fa fa-fw fa-shield',
    ));
    CSF::createSection($prefix, array(
        'id'    => 'user',
